       OR NOT (NEW.`template_id` <=> OLD.`template_id`) OR NOT (NEW.`purpose` <=> OLD.`purpose`) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'device credential identity is immutable';
    END IF;
END
-- @@
DROP TRIGGER IF EXISTS `trg_device_credentials_revocation_immutable`
-- @@
CREATE TRIGGER `trg_device_credentials_revocation_immutable` BEFORE UPDATE ON `device_credentials` FOR EACH ROW
BEGIN
    IF OLD.`status` = 'revoked' AND (NOT (NEW.`status` <=> 'revoked') OR NOT (NEW.`revoked_at` <=> OLD.`revoked_at`)
       OR NOT (NEW.`revoked_by` <=> OLD.`revoked_by`) OR NOT (NEW.`revocation_reason` <=> OLD.`revocation_reason`)) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'device credential revocation is immutable';
    END IF;
END
-- @@
DROP TRIGGER IF EXISTS `trg_gateway_memberships_identity_immutable`
-- @@
CREATE TRIGGER `trg_gateway_memberships_identity_immutable` BEFORE UPDATE ON `gateway_memberships` FOR EACH ROW
BEGIN
    IF NOT (NEW.`tenant_id` <=> OLD.`tenant_id`) OR NOT (NEW.`child_device_id` <=> OLD.`child_device_id`) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'gateway membership identity is immutable';
    END IF;
END
-- @@
DROP TRIGGER IF EXISTS `trg_metadata_operations_terminal_state`
-- @@
CREATE TRIGGER `trg_metadata_operations_terminal_state` BEFORE UPDATE ON `metadata_operations` FOR EACH ROW
BEGIN
    IF OLD.`state` IN ('succeeded', 'failed', 'cancelled') AND NOT (NEW.`state` <=> OLD.`state`) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'metadata operation terminal state is immutable';
    END IF;
END
-- @@
DROP TRIGGER IF EXISTS `trg_metadata_operation_items_terminal_state`
-- @@
CREATE TRIGGER `trg_metadata_operation_items_terminal_state` BEFORE UPDATE ON `metadata_operation_items` FOR EACH ROW
BEGIN
    IF OLD.`state` IN ('succeeded', 'failed', 'skipped') AND NOT (NEW.`state` <=> OLD.`state`) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'metadata operation item terminal state is immutable';
    END IF;
END
-- @@
DROP TRIGGER IF EXISTS `trg_metadata_artifacts_z_content_immutable`
-- @@
CREATE TRIGGER `trg_metadata_artifacts_z_content_immutable` BEFORE UPDATE ON `metadata_artifacts` FOR EACH ROW
BEGIN
    IF NOT (NEW.`id` <=> OLD.`id`) OR NOT (NEW.`tenant_id` <=> OLD.`tenant_id`) OR NOT (NEW.`created_at` <=> OLD.`created_at`) OR NOT (NEW.`created_by` <=> OLD.`created_by`) OR NOT (NEW.`operation_id` <=> OLD.`operation_id`) OR NOT (NEW.`purpose` <=> OLD.`purpose`) OR NOT (NEW.`file_owner` <=> OLD.`file_owner`) OR NOT (NEW.`file_object_id` <=> OLD.`file_object_id`) OR NOT (NEW.`file_name` <=> OLD.`file_name`) OR NOT (NEW.`content_type` <=> OLD.`content_type`) OR NOT (NEW.`size_bytes` <=> OLD.`size_bytes`) OR NOT (NEW.`checksum` <=> OLD.`checksum`) THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'metadata artifact content is immutable';
    END IF;
    IF OLD.`state` IN ('expired', 'deleted') AND NEW.`state` IN ('ready', 'staged') THEN
        SIGNAL SQLSTATE '23000' SET MYSQL_ERRNO = 3819, MESSAGE_TEXT = 'metadata artifact lifecycle cannot move backward';
    END IF;
END
